package xapi.jre.model;
import org.junit.Test;import static org.junit.Assert.*;import com.sun.net.httpserver.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import xapi.model.api.*;import xapi.model.content.ModelText;import xapi.model.impl.ModelUtil;import xapi.util.api.*;
/** A domain adapter reuses the one existing transport without accepting arbitrary path syntax. */
public class ModelOperationHookTest {
 static class Client extends ModelServiceHttp {Client(String endpoint,ModelModule module){super(endpoint,module,2000);}void operation(String path,String type,SuccessHandler<String> callback){postModelOperation(path,type,"command",response->{if(response.statusCode()!=200)throw new IllegalStateException("status");return response.body();},callback,null);}}
 static ModelModule module(){ModelModule m=new ModelModule();m.setModuleName("hook-test");m.setUuid("hook-v1");m.addManifest(ModelUtil.createManifest(ModelText.class));return m;}
 @Test public void rejectsUnsafeOperationOrUnknownTypeBeforeTransport()throws Exception{Client c=new Client("http://127.0.0.1:1/model",module());for(String op:new String[]{"../complete","complete?x","/complete","complete/extra","","complete\n"}){CompletableFuture<String> f=new CompletableFuture<>();c.operation(op,"text",SuccessHandler.handler(f::complete,f::completeExceptionally));try{f.get(1,TimeUnit.SECONDS);fail();}catch(ExecutionException e){assertTrue(e.getCause() instanceof IllegalArgumentException);}}CompletableFuture<String> f=new CompletableFuture<>();c.operation("complete","unregistered",SuccessHandler.handler(f::complete,f::completeExceptionally));try{f.get(1,TimeUnit.SECONDS);fail();}catch(ExecutionException e){assertTrue(e.getCause() instanceof IllegalArgumentException);}}
 @Test public void literalDomainOperationUsesExistingModuleAndBodyTransport()throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);AtomicInteger requests=new AtomicInteger();server.createContext("/model/complete",exchange->{requests.incrementAndGet();assertEquals("hook-test",exchange.getRequestHeaders().getFirst("X-Gwt-Module"));assertEquals("text",exchange.getRequestHeaders().getFirst("X-Model-Type"));byte[] result="canonical-ack".getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,result.length);exchange.getResponseBody().write(result);exchange.close();});server.start();try{Client c=new Client("http://127.0.0.1:"+server.getAddress().getPort()+"/model",module());CompletableFuture<String> f=new CompletableFuture<>();c.operation("complete","text",SuccessHandler.handler(f::complete,f::completeExceptionally));assertEquals("canonical-ack",f.get(5,TimeUnit.SECONDS));assertEquals(1,requests.get());}finally{server.stop(0);}}
}
